# 8192 candidates. batch_fold can handle up to 4000. Let me write to file and feed in 3 chunks.
import itertools, json, random
base=list('AAGGGGGGGGAAAAAAAGAGGGGGGAAAACCCCCCAGGGGGGGAAAACCCCCCCACAAAAAAACCCCCCCCAA')
cands=set()
for p17,p55 in [('G','C'),('C','G')]:
    for v15 in 'AUCG':
        for v16 in 'AUCG':
            for v18 in 'AUCG':
                for v54 in 'AUCG':
                    for v56 in 'AUCG':
                        for v57 in 'AUCG':
                            s=list(base)
                            s[15]=v15;s[16]=v16;s[17]=p17;s[18]=v18
                            s[54]=v54;s[55]=p55;s[56]=v56;s[57]=v57
                            cands.add(''.join(s))
cands=sorted(cands)
print(len(cands))
random.seed(1); random.shuffle(cands)
for i in range(0,len(cands),2800):
    chunk=cands[i:i+2800]
    with open(f'/tmp/L_{i}.json','w') as f:
        json.dump(chunk,f)
print('chunks written')
EOF
